def parse_csv_line(line):
    """Parse a single CSV line, respecting quoted fields with embedded commas and escaped quotes."""
    fields = []
    current_field = []
    in_quotes = False
    i = 0

    while i < len(line):
        char = line[i]

        if not in_quotes:
            if char == '"':
                in_quotes = True
            elif char == ',':
                fields.append(''.join(current_field))
                current_field = []
            else:
                current_field.append(char)
        else:
            if char == '"':
                # Check for escaped quote (doubled quote)
                if i + 1 < len(line) and line[i + 1] == '"':
                    current_field.append('"')
                    i += 1  # Skip the next quote
                else:
                    in_quotes = False
            elif char == ',':
                # Comma inside quoted field is part of the field value
                current_field.append(char)
            else:
                current_field.append(char)

        i += 1

    # Append the last field
    fields.append(''.join(current_field))

    return fields
