    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0
    for c in s:
        current_value = vals[c]
        if current_value < prev_value:
            total -= prev_value
        else:
            total += current_value
        prev_value = current_value
    return total
