def is_balanced(s):
    stack = []
    matching_bracket = {')': '(', ']': '[', '}': '{'}

    for c in s:
        if c in matching_bracket.values():
            stack.append(c)
        elif c in matching_bracket.keys():
            if not stack or stack[-1] != matching_bracket[c]:
                return False
            stack.pop()

    return len(stack) == 0
```

