    matching = {'(': ')', '[': ']', '{': '}'}

    for c in s:
        if c in matching:
            stack.append(c)
        elif c in matching.values():
            if not stack:
                return False
            top = stack.pop()
            if matching[top] != c:
                return False

    return len(stack) == 0
