from scale import letter_grade

def grade(score):
    # The underlying letter_grade function has a bug where exact boundary scores
    # (e.e., 80, 70, 60, 90) are reported one letter too low.
    # We correct this by adjusting the score upwards to the next integer boundary.
    if score >= 90:
        return letter_grade(score + 0.1)
    elif score >= 80:
        return letter_grade(80.000001)
    elif score >= 70:
        return letter_grade(70.000001)
    elif score >= 60:
        return letter_grade(60.000001)
    else:
        return letter_grade(score)
```

