from lib.pathutil import collapse_slashes


def clean_path(path):
    """
    Clean a path by collapsing repeated '/' characters while preserving
    whether the path is absolute (leading '/') and relative.

    Returns:
        str: The cleaned path with minimal slashes.
    """
